import {createApi} from './focus-api.mjs';
import {esc} from './customer-shared.mjs';

const api=createApi(),notice=document.querySelector('#notice'),gate=document.querySelector('#gate'),content=document.querySelector('#content');
const fields=['caseId','purchaseId','paypalOrderId','learnerId','customerName','email','courseId','amount','currency'];
const labels={caseId:'PayTrace case ID',purchaseId:'Store purchase ID',paypalOrderId:'PayPal order ID',learnerId:'Learner ID',customerName:'Buyer name',email:'Purchase email',courseId:'Course ID',amount:'Amount',currency:'Currency'};
const example={purchase:{case_id:'CL-STORE-10001',purchase_id:'store-10001',paypal_order_id:'SANDBOX-ORDER-ID',learner:{id:'learner-10001',name:'Alex Rivera',email:'alex@example.test'},product:{course_id:'course-light',amount_cents:12800,currency:'USD'}}};
document.querySelector('#result').insertAdjacentHTML('beforebegin','<section class="panel replay" id="replay"><div class="section-head"><span class="eyebrow">PREVENTION STUDIO / REHEARSAL</span><span class="chip">Read only</span></div><h2>Would a new mapping handle the next purchases?</h2><p>Paste a JSON array of 1–10 fictional or sandbox store events. PayTrace compares your selected fields with the saved mapping and reports only validity and changed field names. No event values, buyer details, or PayPal references appear in the results.</p><label for="replay-samples">Store event samples (JSON array)</label><textarea id="replay-samples" spellcheck="false"></textarea><div class="actions"><button id="replay-run">Rehearse selected mapping</button></div><div id="replay-result" role="status"></div><small>Rehearsal does not call PayPal, save a draft, create a case, or grant access. A valid mapping still needs a fresh matching sandbox capture before activation.</small></section>');
let paths=[],saved={mapping:null,revision:0,active:false},loading=false;
const sample=()=>{try{const value=JSON.parse(document.querySelector('#sample').value);if(!value||Array.isArray(value)||typeof value!=='object')throw Error();return value;}catch{throw Error('Paste one valid JSON object from your store.');}};
const say=(message,error=false)=>{notice.textContent=message;notice.classList.toggle('error',error);};
const busy=async(button,label,work)=>{if(loading)return;loading=true;const previous=button.textContent;button.disabled=true;button.textContent=label;try{await work();}catch(e){say(e.message||'The request could not be completed.',true);}finally{loading=false;button.disabled=false;button.textContent=previous;}};
function selectedMapping(){if(!paths.length)throw Error('Suggest or load field paths before continuing.');return {fields:Object.fromEntries(fields.map(field=>[field,document.querySelector('[data-field="'+field+'"]').value])),amountMode:document.querySelector('#amount-mode').value};}
function renderFields(mapping){const options='<option value="">Choose a source…</option>'+paths.map(item=>'<option value="'+esc(item.path)+'">'+esc(item.path)+' · '+esc(item.type)+'</option>').join('');document.querySelector('#fields').innerHTML=fields.map(field=>'<label>'+esc(labels[field])+'<select data-field="'+field+'">'+options+'</select></label>').join('');for(const field of fields)document.querySelector('[data-field="'+field+'"]').value=mapping?.fields?.[field]||'';document.querySelector('#amount-mode').value=mapping?.amountMode||'cents';}
function showSaved(){document.querySelector('#draft-status').textContent=saved.mapping?'Saved revision '+saved.revision+(saved.active?' · active':' · draft only'):'No saved mapping yet.';const badge=document.querySelector('#activation-state');badge.textContent=saved.active?'Active · sandbox capture checked':'Draft only';badge.classList.toggle('active',saved.active);}
function showPreview(result){const purchase=result.purchase,payment=result.payment;document.querySelector('#result').hidden=false;document.querySelector('#result-body').innerHTML='<div class="preview-grid">'+[['Case',purchase.caseId],['Store purchase',purchase.purchaseId],['PayPal order',purchase.paypalOrderId],['Learner',purchase.learnerId],['Course',purchase.courseId],['Amount',new Intl.NumberFormat(undefined,{style:'currency',currency:purchase.currency}).format(purchase.amount/100)]].map(([label,value])=>'<div><small>'+esc(label)+'</small><strong>'+esc(value)+'</strong></div>').join('')+'</div><p class="proof">'+esc(payment.reason)+'</p><p class="subtle">No case was created and no customer access changed.</p>';}
async function suggest(){const result=await api('connector/suggest',{sample:sample()});paths=result.paths;renderFields(saved.mapping||result.mapping);document.querySelector('#method').textContent=result.mode==='ai'?'AI suggested · merchant review':'Field-name suggestion';say(result.notice);}
async function init(){if(!window.COURSELATCH_RUNTIME?.backend){gate.hidden=false;gate.innerHTML='<h2>Use the server-backed app</h2><p>The static preview cannot save a merchant connection.</p>';return;}if(window.COURSELATCH_RUNTIME?.authRequired){const auth=await api('auth/session');if(!auth.account?.owner){location.href='account.html';return;}}await api('state');const identity=await api('identity');if(!identity.operator){gate.hidden=false;gate.innerHTML=window.COURSELATCH_RUNTIME?.authRequired?'<h2>Merchant access required</h2><p>An Admin or Manager must open this workspace to configure a connector.</p><a href="account.html">Merchant account →</a>':'<h2>Unlock merchant controls</h2><p>Use the demo operator key provided by your workspace administrator. The key is checked by the server.</p><form id="unlock"><label>Operator key<input type="password" name="key" autocomplete="off" required></label><button class="primary">Unlock studio</button></form>';gate.querySelector('form')?.addEventListener('submit',async e=>{e.preventDefault();await busy(e.submitter,'Unlocking…',async()=>{await api('operator',{key:new FormData(e.target).get('key')});gate.hidden=true;content.hidden=false;await load();say('Merchant controls unlocked.');});});return;}content.hidden=false;await load();}
async function load(){saved=await api('connector/mapping');showSaved();document.querySelector('#sample').value=JSON.stringify(example,null,2);document.querySelector('#replay-samples').value=JSON.stringify([example],null,2);if(saved.mapping)say('Saved mapping loaded. Use Suggest field mapping to load sources from your event before testing.');if(location.hash==='#replay')document.querySelector('#replay').scrollIntoView({block:'start'});}
document.querySelector('#suggest').onclick=e=>busy(e.target,'Reading field names…',suggest);
document.querySelector('#example').onclick=()=>{document.querySelector('#sample').value=JSON.stringify(example,null,2);paths=[];document.querySelector('#fields').innerHTML='';document.querySelector('#result').hidden=true;say('Example restored. Suggest the field mapping to continue.');};
document.querySelector('#preview').onclick=e=>busy(e.target,'Validating…',async()=>{const result=await api('connector/preview',{sample:sample(),mapping:selectedMapping(),verifyPayPal:false});showPreview(result);say('Mapping valid. Payment has not been checked.');});
document.querySelector('#save').onclick=e=>busy(e.target,'Saving draft…',async()=>{const result=await api('connector/mapping',{sample:sample(),mapping:selectedMapping(),expectedRevision:saved.revision});saved=result;showSaved();say('Draft saved. Any earlier activation was removed until a matching PayPal capture is verified.');});
document.querySelector('#activate').onclick=e=>busy(e.target,'Checking PayPal…',async()=>{if(!saved.mapping)throw Error('Save a valid draft mapping first.');if(JSON.stringify(selectedMapping())!==JSON.stringify(saved.mapping))throw Error('Your field choices differ from the saved mapping. Save the draft first.');const result=await api('connector/activate',{sample:sample(),expectedRevision:saved.revision});saved=result;showSaved();showPreview({purchase:result.purchase||{},payment:result.payment});say('Connection active. Future events still receive a fresh PayPal check before a case is created.');});
document.querySelector('#replay-run').onclick=e=>busy(e.target,'Rehearsing…',async()=>{let events;try{events=JSON.parse(document.querySelector('#replay-samples').value)}catch{throw Error('Paste a valid JSON array of 1–10 events.');}const result=await api('prevention/replay',{events,mapping:selectedMapping()});document.querySelector('#replay-result').innerHTML='<p class="proof">'+esc(result.proposedValid)+' of '+result.rows.length+' samples valid with selected mapping'+(result.currentValid===null?' · no saved mapping to compare':' · '+esc(result.currentValid)+' valid with saved mapping')+'.</p><div class="replay-grid">'+result.rows.map(row=>'<div><strong>Sample '+row.sample+'</strong><span>Saved: '+(row.currentValid===null?'not set':row.currentValid?'valid':'needs review')+'</span><span>Selected: '+(row.proposedValid?'valid':'needs review')+'</span><small>Changed fields: '+esc(row.changedFields.join(', ')||'none')+'</small></div>').join('')+'</div><p class="subtle">'+esc(result.notice)+'</p>';say('Read-only rehearsal complete. No connector change was saved.');});
init().catch(e=>{gate.hidden=false;gate.innerHTML='<h2>Connection unavailable</h2><p>Refresh this page after the merchant workspace is ready.</p>';say(e.message||'Could not load the studio.',true);});
